const triggerItem = $('Telegram Trigger').first().json;
const rawMessage = (triggerItem.message?.text || '').trim();
const telegramUserId = triggerItem.message?.from?.id;
const chatId = triggerItem.message?.chat?.id;

let aiRaw = '';
try {
  // Support Groq (OpenAI-compatible choices[0].message.content)
  if ($json.choices && $json.choices[0]?.message?.content) {
    aiRaw = $json.choices[0].message.content;
  } else if ($json.candidates && $json.candidates[0]?.content?.parts?.[0]?.text) {
    // Support Gemini (candidates[0].content.parts[0].text)
    aiRaw = $json.candidates[0].content.parts[0].text;
  }
} catch (e) {
  aiRaw = '';
}

let parsed = {};
try {
  const cleaned = aiRaw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

let type = (parsed.type || 'expense').toLowerCase().trim();
if (type !== 'expense' && type !== 'income') {
  type = 'expense';
}

let category = (parsed.category || '').trim();
const validCategories = ['Makanan', 'Belanja', 'Transportasi', 'Kesehatan', 'Tagihan', 'Pendapatan'];
if (!validCategories.includes(category)) {
  category = type === 'income' ? 'Pendapatan' : 'Belanja';
}

let amount = Number(parsed.amount) || 0;
let isValid = amount > 0 && !isNaN(amount);

let description = (parsed.description || rawMessage).trim();
if (!description || description.toLowerCase() === 'non-transaksi' || description.toLowerCase() === 'bukan transaksi') {
  description = rawMessage.trim();
}

// =========================================================================
// RESILIENT LOCAL NLP / REGEX FALLBACK (Jika AI Quota Limit / Error / Offline)
// =========================================================================
if (!isValid) {
  const lowerMsg = rawMessage.toLowerCase();
  let detectedAmount = 0;

  // Pola nominal: 850rb, 850 rb, 850ribu, 15k, 3jt, 3 jt, 3juta, 25000, 25.000, 25,000
  const jtMatch = lowerMsg.match(/(\d+(?:[.,]\d+)?)\s*(?:jt|juta)/);
  const rbMatch = lowerMsg.match(/(\d+(?:[.,]\d+)?)\s*(?:rb|ribu|k)/);
  const numMatch = lowerMsg.match(/(?:rp\.?\s*)?(\d{1,3}(?:[.]\d{3})+|\d{4,})/);

  if (jtMatch) {
    detectedAmount = Math.round(parseFloat(jtMatch[1].replace(',', '.')) * 1000000);
  } else if (rbMatch) {
    detectedAmount = Math.round(parseFloat(rbMatch[1].replace(',', '.')) * 1000);
  } else if (numMatch) {
    detectedAmount = parseInt(numMatch[1].replace(/\./g, ''), 10);
  }

  if (detectedAmount > 0) {
    amount = detectedAmount;
    isValid = true;

    // Deteksi tipe (pemasukan vs pengeluaran)
    if (lowerMsg.includes('gaji') || lowerMsg.includes('income') || lowerMsg.includes('pemasukan') || lowerMsg.includes('bonus') || lowerMsg.includes('cashback') || lowerMsg.includes('dapat uang') || lowerMsg.includes('terima')) {
      type = 'income';
      category = 'Pendapatan';
    } else {
      type = 'expense';
      // Deteksi kategori
      if (lowerMsg.includes('makan') || lowerMsg.includes('minum') || lowerMsg.includes('kopi') || lowerMsg.includes('lunch') || lowerMsg.includes('dinner') || lowerMsg.includes('snack') || lowerMsg.includes('sarapan') || lowerMsg.includes('bakso') || lowerMsg.includes('mie') || lowerMsg.includes('ayam')) {
        category = 'Makanan';
      } else if (lowerMsg.includes('kos') || lowerMsg.includes('listrik') || lowerMsg.includes('token') || lowerMsg.includes('wifi') || lowerMsg.includes('air') || lowerMsg.includes('pdam') || lowerMsg.includes('pulsa') || lowerMsg.includes('kuota') || lowerMsg.includes('tagihan')) {
        category = 'Tagihan';
      } else if (lowerMsg.includes('bensin') || lowerMsg.includes('pertalite') || lowerMsg.includes('pertamax') || lowerMsg.includes('ojol') || lowerMsg.includes('grab') || lowerMsg.includes('gojek') || lowerMsg.includes('parkir') || lowerMsg.includes('tol') || lowerMsg.includes('angkot') || lowerMsg.includes('bus')) {
        category = 'Transportasi';
      } else if (lowerMsg.includes('obat') || lowerMsg.includes('apotek') || lowerMsg.includes('dokter') || lowerMsg.includes('klinik') || lowerMsg.includes('vitamin') || lowerMsg.includes('rumah sakit')) {
        category = 'Kesehatan';
      } else {
        category = 'Belanja';
      }
    }
    description = rawMessage;
  }
}

if (description.length > 255) {
  description = description.substring(0, 255);
}

const escapedDescription = description.replace(/'/g, "''").replace(/\\/g, '\\\\');
const escapedRawMessage = rawMessage.replace(/'/g, "''").replace(/\\/g, '\\\\');

return [{
  json: {
    telegram_user_id: telegramUserId,
    chat_id: chatId,
    raw_message: rawMessage,
    escaped_raw_message: escapedRawMessage,
    type: type,
    category: category,
    amount: amount,
    description: description,
    escaped_description: escapedDescription,
    is_valid: isValid
  },
  pairedItem: { item: 0 }
}];

parameters.query:
=SELECT 
  COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) AS today_total_expense,
  COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) AS today_total_income
FROM transactions
WHERE telegram_user_id = {{ $('Code: Parse & Validate AI Output').first().json.telegram_user_id }}
  AND transaction_date >= CURRENT_DATE;

